  launcher?: 'local-dev-server-runner' | 'local-provisioning-worker-runner';
  logFile: string;
  pid: number;
  profile: RuntimeProfile;
  startedAt: string;
};

type LocalRuntimeCommandForDriftCheck = 'migrate' | 'reconcile' | 'up' | 'update';

type LocalRuntimeFileDeps = Readonly<{
